import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"咸","description":"高岛易断 - 咸","frontmatter":{"title":"咸","description":"高岛易断 - 咸"},"headers":[],"relativePath":"zh/classics/takashima/031.md","filePath":"zh/classics/takashima/031.md"}'),i={name:"zh/classics/takashima/031.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="咸" tabindex="-1">咸 <a class="header-anchor" href="#咸" aria-label="Permalink to “咸”">​</a></h1><h2 id="咸-1" tabindex="-1">咸 <a class="header-anchor" href="#咸-1" aria-label="Permalink to “咸”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>咸：亨，利贞，取女吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《咸》，亨通也。男女相合者七卦，《恒》是男女皆长，《既济》、《未济》中男中女，《渐》、《归妹》以少遇长，《损》虽男女皆少，而女下于男，皆未若《咸》之亨而正也。“娶女吉”者，婚礼自纳采以至亲迎，皆男下于女，六礼不备，贞女不行。《关雎》一篇所云，“窈窕淑女，君子好逑”，娶女之吉，于此可见。《诗·注》谓淑女有幽闲贞静之德，是即“利贞”之旨也。《咸》以《兑》泽《艮》山二气相感，感而遂通，然少男少女，情好易通，得正则吉，失正则凶，故曰“利贞”。娶女之吉，惟其贞也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>山上有泽，咸，君子以虚受人。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>卦象为“山上有泽”，是山气下交，泽气上交，得以上下相成也。天下至静而虚者莫如山，惟山以虚，翕受泽气。君子体此象以容人之善，故能湛其心于寂然不动之时，定其性于廓然大公之地。古来如舜之取人为善，禹之拜昌言，周公之吐哺握发，一皆虚己而受人者也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问战征：军队前进，防有坑陷，山谷间防有埋伏，固守城池，防敌兵潜通地道，皆当谨慎。</p><p>○　问营商：山泽为生财之地，即财源也。“以虚受人”，是以购入物产，贩运转售，必大获利。</p><p>○　问功名：“山上”者高附之象，“山上有泽”，泽者，积水低洼之处。有居高思危之意，惟宜虚己待人，功名可长保也。</p><p>○　问家宅：是宅必傍山临水，知其所止，吉。</p><p>○　问疾病：是虚弱之症，宜服滋补之剂。</p><p>○　问婚姻：卦为山泽通气，主两姓和好，大吉。</p><p>○　问讼事：两造必是少年意气相争，讼宜和解而止为善。</p><p>○　问六甲：生男。</p><p>○　问失物：必坠入空洞有水之处，不能复得。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“拇”者足之大指，初居爻首，为感之始，其感尚微，譬如足之有指，指即小动，未常移步，以喻人心初感而未动，始有其志而已。《象》曰“志在外也”，外谓九四，以初与四相应，故曰“在外”。志者心之所之也，谓第有其志，未尝躁动，是以不言吉凶。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问战征：是兵刃初交之会，应在第四日，可以得胜。</p><p>○　问营商：必是初次贸易，货物已办，尚未发行也。</p><p>○　问功名：必能一举成名，有捷足先登之兆。</p><p>○　问家宅：有迁居外地之意。</p><p>○　问疾病：是足指初起一毒，宜外用敷药调治。</p><p>○　问婚姻：初六应在九四，以《艮》男求婚于《兑》女也，为结缡之吉。</p><p>○　问六甲：生男，是初胎也。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治二十三年，占某贵显运气，筮得《咸》之《革》。</p><p>断曰：此为《咸》卦初爻，拇为足指，是人身最小之体，其动与不动，本不足关轻重也。初爻应在九四，四比近尊位，此占当以应爻属贵显，初爻则为来占之人也。今初爻《咸》之初，某贵显自幕府至今，备尝困苦，今虽年老而志愿犹奢，凡有指划，《咸》皆悦从。《象》曰：“志在外也”，盖在贵显之志，谓方今国家要务，专以外交为重也。知贵显老运未艾。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“腓”为胫，或曰足肚，是无骨之处，盖在拇之上股之下也。腓不能自动，随足而动，足动而凶，则腓亦失其吉矣。然动则为凶，而静居则吉，故《象传》曰；“虽凶居吉，顺不害也。”六二以阴居阴，其性本静，能顺其性而不动，自可免害而获吉也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问战征：宜固守不动，斯可免害。</p><p>○　问营商：不利行商，利坐贾。</p><p>○　问功名：只可依人成事，未能远到。</p><p>○　问疾病：按腓病也，必是四肢痿痹之症，只可坐卧，不能步行也。</p><p>○　问婚姻：婚事既成，恐有变动，能以顺自守，虽凶终吉。</p><p>○　问六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>华族某君来谓余曰：顷者知己某，以数年刻苦，新创一技，特许专卖，余因贷之以资金，但不知新创之技，果得广行否？亦不知贷与之资金损益如何？请筮之。筮得《咸》之《大过》。</p><p>断曰：《咸》者为山泽通气之卦，是二物相依，相互为用也。某友发明一物，藉君之资金，得以成业，是某友与君实相依为用，其事业之广行也可必矣。腓者足肚也，腓不自动，随足之动而动，以喻资金之通用，全藉货物之贩运，而资金亦随之而运动也。在此业新出，未免一时贩售有碍，当居积以待，自能获利，始虽凶而终吉也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>此爻居下体之上，上体之下，为股之象，股者随上下而动，不能自主者也。九三以阳居阳，与上六之阴相应，舍上六而比初二，以为动止，率此以往，其吝可知。三为《艮》卦之主，《艮》为股，故曰“股”，《艮》又为执，故曰“执”。《艮》本止也，三以感而思动，又牵率初二，使之皆动，故曰“执其随”。《象传》曰“亦不处也”，“亦”者，谓率拇腓而俱动也。“志在随人，所执下也”，“随人”者，谓随上也；“执下”者，谓执初与二也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问战征：宜退守，不宜往攻。</p><p>○　问营商：凡商业合出资本，谓之股分，必举一人以主其业，乃主业者，不能自主，而徒随人以为上下，其业必难获利。</p><p>○　问功名：随声附名，其品下矣，必难制胜。</p><p>○　问家宅：宅近《艮》山，本可安处，占者不愿处此，殆欲随人他迁也，恐所往吝矣。</p><p>○　问婚姻：咎在过听执柯者之言，恐所适非偶。</p><p>○　问六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某来，请占运气，筮得《咸》之《萃》。</p><p>断曰：卦体《艮》山《兑》泽，山得泽而生润，泽得山而发源，是为山泽通气，阴阳相感，正元运旺相之象也。足下占得第三爻，三爻为内卦之主，与上六相应，九三为阳，上六为阴，感而思动，故曰“咸其股”。股属下体，亦阴象也。卦本为少男少女两相爱悦，三爻“志在随人”，牵率其下而皆往，则其溺情尤甚，吝复何辞？论现年运气，未尝不佳，乃因溺志色欲，阳被阴累，防致疾厄，宜慎宜戒！友人听之，始而如有所感，继而溺情不悟，以致终身落魄不偶。哀哉！</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四当三阳之中，居心之位，《咸》之主也。初之拇，二之腓，三之股，五六之脢舌辅颊，皆从心而发，故心不言感，以万感皆由心而生也。夫心之本体，本灵明不昧，寂然不动，自有所感而心动焉。动则有悔，欲其亡悔，惟贞而已；贞者正也，正则吉而悔亡。然人心不能无感，而感亦不能皆正，不正则心受其害，而悔随感生，何以得吉？“憧憧”者急遽之状，“往来”者忙促之形，“憧憧往来”，甚言纷至叠来，私意错乱，害累丛生。下之拇、腓、股，上之脢、舌、辅，亦皆纷纷而动，但见其“朋从”耳，则此心岂复有一息之泰定哉！《象传》曰“贞吉悔亡，未感害也”，谓贞则其心无私，未感之先，心本洞然，故曰“未感害也”。“憧憧往来，未光大也”，谓物感迭来，不能无思无欲，故曰“未光大也”。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问战征：军中全以主帅为心，当万军纷集，以一帅镇定之，斯令行禁止，寂然不动，否则扰乱错杂，灾害生焉。</p><p>○　问营商：商务虽在谋利，亦以得贞为吉，若见利忘义，则群焉争夺，不夺不餍，害有不可胜言者矣。</p><p>○　问功名：四爻以阳居阳，位近至尊，功名显达，其象贞吉，然得不以正，害即随之，最宜谨慎。</p><p>○　问家宅：其宅必临通衢往来之地，邪正杂处，交际最宜慎择。</p><p>○　问疾病：必是心神恍惚之症，宜静养。</p><p>○　问婚姻：防女家闺范不谨。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十二年，某缙绅来，请占某贵显气运，筮得《咸》之《蹇》。</p><p>断曰：四爻以阳处阴，为内卦之始，比近九五，是贵显之象也。为某贵显占气运，筮得四爻，四当三阳之中，中居心位，心为百体之主，心贞则百体皆贞，犹言大臣正躬率物，百僚皆从令焉，故曰“贞吉悔亡”，此固某贵显之能事也。苟心有不正，必致庶事丛脞，朋党纷起，始则害在一身，终则害延一国，皆由一心之不正，阶之厉也。在某贵显，秉心正直，国而忘家，公而忘私，能以天下为己任，古所称正一己以正天下者，某贵显有焉，庶民所仰望者，正未有艾也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>按：《注》云“，脢者心上口下”，马云“脢背也”。《博雅》“胛谓之脢”，即背脢也；心在前，背在后，是不动之处也。《艮》之象曰“艮其背”，知背为《艮》之所止；爻辞曰“咸其脢”，殆即孟子所云，“君子所性，根于心，盎于背，施于四体，四体不言而喻”者是也。五爻以阳刚中正之德，居君上之位，下应六二。六二日“咸其腓”，腓为足肚，不能自动，五曰“咸其脢”，脢为背脊，亦不能自动，故其《咸》也，若有不感而感，而其动也，亦若有不动而动。不动而动，在脢亦不自知其动也，悔何有焉？《象传》曰“志末”，谓此乃不感而感，感之至也。彼初之“志在外”，三之“志在随人”，皆有心而感者，抑末矣。一说：《象传》“志末也”者，谓尊居九五，当抚恤亿兆之心，志愿斯为大矣，若甘作自安之计，期免目前之悔，其志不亦微末乎？</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问战征：宜潜袭其后以攻敌背，有胜无败。</p><p>○　问营商：《象》曰“志末”，末微小也，知其商业不大，利亦微薄。</p><p>○　问功名：背者，败北也，知所求未必成名。</p><p>○　问疾病：台背，寿征也，知病即愈，无悔，且获多寿。</p><p>○　问六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十一年，缙绅某来，请占某贵显气运，筮得《咸》之《小过》。</p><p>断曰：凡卦例以九五为君位，然《乾》为君为父也，而臣子亦得占之，《坤》为臣为民，而君父亦得占之，《易》道不拘一例也。《咸》卦《艮》山《兑》泽，二气相感，是以“天地感而万物化生，圣人感人心，而天下和平，则知大臣当国，皆以至诚感孚夫上下者也。今占某贵显气运，得第五爻，爻辞曰“咸其脢”，脢谓背脊处，前为阳，背为阴，心背之间，阴阳相感，亦痛疼相关。某贵显念切民艰，自能恫痞在抱，不容以隔膜相视也，必无悔焉。至其后运，定臻台背之寿，其福未可限量矣。《象传》曰“志末也”，谓目下志愿犹未光大也。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“辅”者，颊之里，“颊”者辅之表，舌在口中，舌动则辅颊随之。此爻阴柔不中，居卦之极，比近尊位，专以谗口惑君者也。是巧佞之小人，为圣人所深恶也，故不系凶辞，而其凶自见矣。《象传》曰“腾口说也”，腾谓张口骋辞，或曰虚也，谓无诚实，徒夸虚说以诳世，《咸》道薄矣。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问战征：防有间谍窥探。</p><p>○　问营商：恐有口舌之祸。</p><p>○　问功名：可献策陈言，当得召用。</p><p>○　问家宅：主人口不睦，口角起争。</p><p>○　问疾病：呓语谵言，心魂不安，宜祷。</p><p>○　问婚姻：中人之言，未可全信。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十五年，岩平县众议院议员佐藤昌藏氏来曰：今回地租修正之议兴，奥羽诸县已编地租增加之部，然在我县下，地质不饶，增加地租，甚觉不当为此，请占院议结果。筮得《咸》之《遁》。</p><p>断曰：《兑》为口，辅颊舌皆所以言，此即议院之证验也。今占地租增加，而得《咸》之上六，《咸》者感也，凡有所议，必得上下直诚感通，其事可通行无阻。兹徒以空谈相竞而无实惠，其何能令民之遵从乎！后佐藤氏来谢曰：《易》断真不虚也！</p>',94)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
